from model import *
c=C(5,'接口设计与宿主适配','第一篇  系统总体设计')
S(c,'本地业务服务接口',
P('领域函数的调用契约','''本地领域接口采用普通 TypeScript 函数。调用者提供 Flight，函数返回校验信息、派生质量或 Result。函数不读取页面输入框，不隐式访问当前路由，也不自行修改浏览器存储。这使函数调用具有明确的输入输出边界。

validate 返回字符串数组，空数组表示输入满足当前数据规则。weights 只计算质量关系，调用者在使用其值作正式结果前仍需要校验输入。calculate 内部执行 validate，因而结果对象可以独立表达 invalid 和 unsupported 等状态。

parseFlight 是文本边界接口，它可能抛出 JSON 语法或业务校验异常。页面以统一动作包装器捕获异常，再转为可见通知。普通的业务拒绝尽量返回结构化状态，文件解析这一类无法形成有效对象的失败则在边界处中断。''',table=T('函数|参数|返回语义','validate|未知对象 / Flight|string[]，当前所有可报告错误\nweights|Flight|payload、zfw、ramp、tow\nparseFlight|JSON 文本|合法 Flight，失败抛错\nsignature|Flight|完整输入与资料的内容表示\ncalculate|Flight|带状态、快照和版本的 Result\nmassConvert 等|数值、源单位、目标单位|换算后的数值'),diagram=D('components','页面与纯函数服务边界',['页面输入','应用状态动作','validate / parseFlight','weights','calculate','Profile'],[(0,1,'编辑'),(1,2,'校验'),(1,3,'派生显示'),(1,4,'请求结果'),(5,4,'限制与数据')])) ,
P('应用动作接口','''状态层把领域函数组合成完整用例。editFlight 形成草稿并清除确认；confirmFlight 校验后记录签名并同步原生页面；runCalculation 要求当前输入已确认且地面目标未变化；archiveResult 只保存当前有效结果。动作名称直接表达业务意图。

这些动作的副作用集中在 publish 和 applyToEfb。前者保存并发布本地状态，后者把确认计划映射到原生组件及开发宿主。页面因此只需要调用动作，不必重复写入 localStorage 或多个 Store 切片。

动作返回与通知各有分工。confirmFlight 返回布尔值，通知文字解释成功或失败原因；currentResult 返回结果或 null，供按钮是否可用以及报告出口共享使用。调用者不应通过某一句中文提示文字判断业务状态。''',table=T('动作|前置数据|状态变化','editFlight(f)|新的 Flight|替换草稿、清空 confirmed\nloadFlight(f)|通过 validate 的对象|载入为草稿并记录来源\nconfirmFlight()|合法当前输入|写入签名、清除地面变化、同步原生\nrunCalculation()|已确认且地面未变|替换最近 Result\narchiveResult()|currentResult 非空|插入历史并限制 20 条\nrestoreHistory(i)|有效记录索引|复制历史 input 为草稿\nreadFuelTarget()|有效燃油目标|更新 rampKg 草稿'),diagram=D('state','应用动作中的主状态变化',['草稿','已确认','有效参考结果','旧结果失效'],[(0,1,'confirmFlight'),(1,2,'runCalculation'),(2,3,'edit / ground change'),(3,1,'重新确认')])) ,
P('错误返回与界面转换','''错误消息来自不同边界，但最终由本地页面统一呈现。字段校验生成可读原因集合；文件选择处理器补充“导入失败，保留原航班”；存储错误优先显示 storageError；参考模型范围问题保存在 Result.errors 中。页面保留错误来源，使用户能够选择合适动作。

当前函数接口没有定义机器可读的错误代码枚举。对于单机中文界面，这种实现简单直接；扩展为外部 API 时，应在保持可读消息的同时增加稳定 code 和字段路径。否则调用者只能解析人类语言，语言变更就会破坏接口兼容性。

扩展错误对象可采用 code、field、message、details 的结构。业务状态仍由 status 表示，错误对象解释状态原因。一个结果可以有多个字段错误，但只能有一个当前计算状态。''',diagram=D('entity','错误信息的分层组织',[['输入错误','字段路径','范围与类型原因'],['计算状态','invalid / unsupported','reference-only'],['界面消息','简明中文提示','对应处理入口']],[(0,1,'决定'),(1,2,'解释')]),table=T('错误来源|当前表现|合适的界面位置','字段校验|错误字符串集合|表单下方或状态区\nJSON 解析|捕获异常|导入反馈\n模型范围|Result.errors|结果卡片\n存储失败|storageError|全局本地状态消息\n弹窗阻止|报告窗口未打开|导出操作消息\n扩展 API|code + field + message|保持可读提示与机器语义')),
P('接口的副作用约束','''相同输入的重量与参考插值不应因页面停留时间而改变；生成时间则是结果元数据中的时间值。纯函数计算与状态动作分开后，业务可以说明哪些输出是数学结果，哪些是会话信息。

文件导出和打印属于出口副作用。它们先取得当前有效结果，再创建文件或窗口，不修改计算输入。归档属于持久化动作，会改变历史数组，但不会修改归档对象中的 input。恢复则相反：它改变当前输入，而不把历史记录本身改写。

这种副作用分配让页面跳转保持轻量。路由切换负责展示页面，不应悄悄确认航班或重算性能。用户看到一个结果页面时，可以根据状态提示判断是否已经计算，而不必猜测导航是否触发了业务更新。''',table=T('接口类别|允许的副作用|不承担的行为','纯规则函数|返回派生对象|页面跳转、存储、网络\n状态动作|更新本地状态并发布|任意读取 DOM\n原生映射|写入兼容 Store 与目标|执行完整飞机物理过程\n文件出口|创建下载资源|修改当前输入\n历史恢复|载入旧输入为草稿|继承旧结果的有效资格\n导航动作|切换内部路由|隐式确认或归档'),diagram=D('lanes','用户动作与副作用边界',[['编辑动作','替换草稿','撤销确认','保存草稿'],['计算动作','检查确认','计算结果','发布结果'],['导出动作','选择有效结果','格式化文件','浏览器下载']])) ,refs=['L-F','L-S','L-U'])
S(c,'原生页面兼容接口',
P('兼容层的输入输出','''原生仪表盘和签派页面依赖既有 simBrief 切片结构。本地兼容层并不调用在线签派服务，而是把 Flight 转成该结构。输入是本地领域对象，输出是完整 SimBriefData 形状及一组目标变量。

映射从 initialState.data 的深复制开始，填入新的航班、重量、燃油和可读资料。完整对象替换比零散字段覆盖更易控制旧数据残留，例如换了目的机场后不应继续显示上一航班的资料片段。

原生名称被保留在兼容层内部。业务说明和界面使用“本地航班”，文件中使用 Flight 的字段；这样历史命名不会误导用户，也不会迫使新接口继承不准确的业务含义。''',diagram=D('sequence','确认航班后的原生兼容提交',['LocalFlightPage','confirmFlight','applyToEfb','Redux / Host'],[(0,1,'保存并确认'),(1,1,'validate + signature'),(1,2,'提交完整 Flight'),(2,2,'复制原生初始结构'),(2,3,'setSimbriefData'),(2,3,'设置目标与导入标志')]),table=T('映射区域|本地来源|目的','航班标识|number、date、机场|原生摘要\n重量|weights 及载荷字段|原生重量卡片\n燃油|rampKg、taxiKg|燃油计划\nloadsheet|输入和质量关系|可读 OFP 内容\n宿主目标|确认后的质量|地面计划联动')),
P('质量与燃油的字段映射','''本地模型用 number 保存质量，原生兼容结构中的许多重量字段使用字符串。转换在 applyToEfb 中集中完成。旅客、行李和额外货物既以各自字段写入，也形成 payload、cargo 和零油重等合计，使原生组件取得预期数据。

燃油结构保持计划含义。planRamp 等于 rampKg，planTakeOff 等于 rampKg-taxiKg。当前映射没有根据航程计算 enrouteBurn，也没有提供独立的计划着陆油量。因此这些占位值不能解释为完整签派燃油计划。

estLandingWeight 当前使用本地 TOW 作为兼容值，适合填充对象结构，却不是经过航程耗油推导的着陆重量。原生着陆计算页面仍应由用户输入本次所需的着陆条件。''',table=T('原生字段|本地表达式|语义说明','weights.payload|pax×(paxKg+bagKg)+freightKg|有效载荷\nweights.cargo|pax×bagKg+freightKg|行李与货物\nweights.estZeroFuelWeight|OEW+payload|零油重\nweights.estTakeOffWeight|ZFW+rampKg-taxiKg|计划起飞重量\nweights.estLandingWeight|当前映射为 TOW|兼容显示占位\nfuels.planRamp|rampKg|停机坪计划油\nfuels.planTakeOff|rampKg-taxiKg|起飞计划油\nfuels.enrouteBurn / planLanding|当前为 0|未建模航程耗油'),diagram=D('formula','确认计划中的质量投影',[['重量投影','Flight 数值 → weights() → 原生字符串字段'],['燃油投影','rampKg、taxiKg → planRamp、planTakeOff']])) ,
P('开发宿主中的目标与样例状态','''确认计划后，本地适配器设置 EMPTY WEIGHT、TOTAL WEIGHT、零油重、全重和目标变量。TOTAL WEIGHT 及 GW 当前按停机坪总重写入，而参考 TOW 已扣除滑行油。区分这两个量，可以解释为什么某些原生页面显示的全重与参考页 TOW 不完全相同。

为了让燃油图具备可读的样例状态，开发宿主按固定密度把 rampKg 转为 US gallon，并按外侧、内侧、中央油箱顺序填入样例量。这个分配是浏览器展示适配，不是飞机加油逻辑，也不模拟时间推进。

计划同步直接调用 host.set，避免把应用主动同步误识别为用户修改目标。原生控件经 SimVar 写入目标时则经过 writeLocal，引发地面变化事件。两条路径的不同是为保持失效语义准确。''',table=T('宿主变量|写入值|用途','EMPTY WEIGHT|oewKg|开发样例空重\nTOTAL WEIGHT|ZFW+rampKg|停机坪总重显示\nL:A32NX_AIRFRAME_ZFW|ZFW|零油重显示\nL:A32NX_AIRFRAME_GW|停机坪总重|原生全重显示\nL:A32NX_FUEL_DESIRED|rampKg|燃油目标\n各油箱 QUANTITY|质量按固定密度换算与分配|燃油示意图'),diagram=D('lanes','应用同步和用户改动的不同写入路径',[['确认同步','applyToEfb','host.set','保持确认'],['地面改动','原生控件','writeLocal','发出变化事件'],['结果选择','读取签名','读取 groundChanged','决定可用性']])) ,
P('反向读取的限定范围','''兼容层采用有边界的反向读取。readFuelTarget 只读取 L:A32NX_FUEL_DESIRED，并检查其为非负有限数，再更新 Flight.rampKg。该函数不读取当前油箱总量，也不自动改变滑行耗油。

载重页面的反向映射更复杂，因为同样的总载荷可以由不同人数、平均重量、行李和货舱分布组成。当前系统没有从座位位图反解全部 Flight 字段。工作台保留明确的总量输入，用户在地面调整后回到工作台确认。

限定反向范围可避免不可逆映射造成的信息损失。例如，仅知道 ZFW 无法唯一确定旅客人数和货物质量。接口设计需要承认这种多对一关系，而不是把原生总重任意拆回一个看似精确的计划。''',diagram=D('components','反向映射的可逆性边界',['Flight 详细输入','原生总量','燃油目标','rampKg 草稿','座位与货舱分布'],[(0,1,'多对一汇总'),(2,3,'明确读取'),(0,4,'目标分配')]),table=T('回读对象|是否有明确逆映射|当前处理','燃油目标质量|是|更新 rampKg\n零油重合计|否|不反推全部载荷字段\n座位位图|需要布局与重量规则|不自动形成完整 Flight\n货舱总量|无法区分行李与额外货物|回工作台核对输入\n实际飞机油量|含过程状态语义|不等同计划目标')) ,refs=['L-S','L-H','EFB'])
S(c,'模拟器变量与事件接口',
P('SimVar 接口形状','''原生页面通过 SimVar.GetSimVarValue 和 SetSimVarValue 读写变量。本地宿主建立同名对象，使用 Map 保存变量名到值的映射，并提供注册式 ID 接口供共享 SDK 使用。该实现让原生调用路径在浏览器中成立。

读取按请求类型返回字符串或数值。数值读取统一调用 Number，解决十进制字符串写入后被下游当作字符串解析的问题；A: 前缀在本地读取时作为普通变量别名处理。未定义值当前回退为 0 或空字符串，这是开发替身的简化约定。

本地适配没有实现 MSFS 全部单位转换。调用方仍需采用已定义字段及单位，质量、体积或角度的特殊变换在对应业务适配中明确处理。真实宿主应按其 API 语义提供单位转换和变量支持信息。''',table=T('接口|参数概念|本地实现','GetSimVarValue|名称、单位|Map 读取并做类型转换\nSetSimVarValue|名称、单位、值|写入并发布相关事件\nGetRegisteredId|名称|登记名称并返回数组下标\nGetRegisteredSimVarValue|注册 ID|按登记名称读取\nSetRegisteredSimVarValue|注册 ID、值|经同一写入路径更新\nGetGlobalVarValue|名称、单位|转入普通读取逻辑'),diagram=D('components','SimVar 注册与读写路径',['原生组件','共享 Hook','SimVar 门面','变量名与 ID 表','本地 Map','变化事件'],[(0,1,'订阅 / 写入'),(1,2,'API 调用'),(2,3,'ID 解析'),(2,4,'读写'),(2,5,'目标变化')])) ,
P('更新节拍与 React Hook','''useSimVar 在初次渲染时取得变量值，随后通过 useUpdate 响应宿主更新事件。Hook 使用时间差判断是否达到 refreshInterval，达到后重新读取变量并更新 React 状态。不同页面可以为不同变量选择不同刷新周期。

本地宿主每 100 ms 向 instrument 节点派发 update 事件。该事件是界面采样节拍，不是飞机仿真步长。React 组件在每个节拍上可以选择读取，也可以因自身刷新间隔尚未到达而跳过。

setter 会调用宿主写接口，同时更新本组件的状态值。这带来即时操作反馈，但该反馈属于本地期望值。下一次宿主采样可能返回另一值，因此对真实持续动作的完成判断仍依赖回读。''',diagram=D('sequence','变量采样与本地反馈',['宿主节拍','useSimVar','SimVar','React 页面'],[(0,1,'update 事件'),(1,1,'判断 refreshInterval'),(1,2,'GetSimVarValue'),(2,1,'返回观测值'),(1,3,'setState'),(3,2,'用户动作 SetSimVarValue')]),table=T('机制|时间语义|作用','本地 update|每 100 ms|驱动采样机会\nrefreshInterval|变量级最小间隔|限制读取频率\n组件初值|首次渲染|提供初始显示\nsetter 本地更新|用户动作后立即|操作反馈\n后续回读|达到采样间隔后|与宿主值重新同步')),
P('Coherent 与监听器适配','''共享代码除直接访问 SimVar 外，还使用 Coherent 和视图监听器。浏览器替身以事件名到回调集合的 Map 实现 on、off 与 trigger，监听器返回可清理句柄。Coherent.call 采用异步函数形状，使调用者可以继续沿用 Promise 调用方式。

本地实现只处理必要的调用子集。例如注册变量写入转到 writeLocal，METAR 查询返回空的气象文本，其他 GET 类调用可返回空集合。它的目的在于建立开发运行边界，而不是复刻所有模拟器服务。

事件订阅需要与组件生命周期对应。注册后持有清理句柄，卸载时移除回调，避免旧页面继续收到事件。状态层对地面变化事件的监听位于初始化入口，避免依据地址栏路径判断内部 MemoryRouter 页面。''',table=T('适配对象|提供的操作|本地语义','Coherent|on / off / trigger / call|事件总线与有限异步调用\nRegisterViewListener|on / trigger / ready|返回本地监听器\nRegisterGenericDataListener|数据回调与发送|命名事件转发\nAceInitialized|启动事件|触发本地 React 挂载\nupdate|周期事件|驱动原生采样 Hook\nlocal-ground-change|业务事件|撤销旧参考结果资格'),diagram=D('components','宿主事件总线',['组件订阅者','on / off','事件回调集合','trigger / emit','变量写入','启动与更新节拍'],[(0,1,'注册 / 清理'),(1,2,'维护回调'),(3,2,'分发'),(4,3,'目标事件'),(5,3,'生命周期事件')])) ,
P('请求完成与状态生效','''模拟器接口中的写请求完成，不等于目标物理过程已经结束。写入燃油目标只表达期望油量，打开地面服务请求只表达操作意图。设备实际可用、连接完成或油量达到目标，需要从后续状态中判断。

在浏览器替身中，部分变量写入会立即体现在 Map 中，因此看起来没有通信延迟。真实宿主则可能有排队、条件拒绝和过程时间。前端业务不能因开发环境响应快，就把所有写入统一解释为完成。

接口设计将期望值、请求状态和观测值并列保存或显示。对于持续动作，界面可在请求接受后进入等待，在观测满足目标条件后进入完成，在超时或拒绝时显示原因。扩展协议的具体字段在下一节定义。''',diagram=D('state','控制请求与观测状态的区别',['目标已编辑','请求已提交','宿主已接受','观测到完成','拒绝或超时'],[(0,1,'发送'),(1,2,'接受回执'),(2,3,'状态满足目标'),(1,4,'拒绝'),(2,4,'超时')]),table=T('信息|能证明什么|不能单独证明什么','目标值|用户希望达到的状态|实际状态已经达到\n写请求返回|接口调用完成|物理动作完成\n接受回执|宿主接受了请求|最终效果出现\n观测快照|某时刻实际回读值|未来状态不再变化\n完成回执|对应动作达到完成条件|其他动作也完成')) ,refs=['L-H','FBW','SIM'])
S(c,'真实后端交换契约',
P('会话与状态快照','''扩展宿主协议以会话为边界。一次会话绑定 sessionId、aircraftId、modelVersion 和 capabilities。前端建立连接后先取得这些信息，再决定哪些控件可用。相同页面可以服务不同宿主，但不能在没有身份确认时混用上一会话的状态。

快照包含递增序号和采样时间。每个数据项同时包含值、单位和质量标志；缺失、无效、过期与正常零值分开表示。前端只接收当前会话内的新快照，较旧序号不会覆盖较新的观测。

该契约是本地宿主向真实模拟器迁移的设计接口，当前静态服务没有实现这些端点。后端由独立系统负责产生快照，EFB 仅消费其公开接口，不直接访问后端机型生产目录。''',diagram=D('entity','宿主会话与快照对象（扩展设计）',[['Session','sessionId / aircraftId','modelVersion / capabilities'],['Snapshot','sessionId / revision','sampledAt / values'],['Value','value / unit','quality / source']],[(0,1,'限定来源'),(1,2,'包含')]),table=T('字段|建议类型|用途','sessionId|string|隔离不同运行会话\naircraftId|string|确认机型身份\nmodelVersion|string|记录后端模型版本\nrevision|integer|识别新旧快照\nsampledAt|UTC 时间|判断时效\nquality|valid / stale / unavailable|区分质量状态')),
P('命令与回执对象','''命令采用唯一 commandId，指定当前 sessionId、操作名、参数和发出时间。后端按请求标识识别重复提交，并返回明确的接受或拒绝信息。持续动作可以继续发送执行与完成状态，前端根据 commandId 关联同一次操作。

命令参数表达目标，而不是任意变量内存地址。例如燃油目标命令携带目标质量与单位，推回命令携带受支持的运动意图。后端拥有实际控制边界，负责判断当前状态是否允许执行。前端的按钮禁用只提供操作引导，不替代后端条件判断。

回执区分 accepted、running、completed、rejected 和 failed。accepted 不是 completed，失败信息包括稳定错误码和可读说明。断线重连后，前端可以查询请求状态，而不是无条件重复发送一次可能已经执行的动作。''',table=T('对象字段|含义|示例语义','commandId|一次命令的唯一标识|重复请求关联\nsessionId|目标会话|禁止跨会话执行\ncommand|领域操作名|setFuelTarget\nparameters|有类型和单位的参数|massKg、rateMode\nstatus|执行阶段|accepted / completed\nerror.code|稳定错误码|条件不满足、能力不支持\nobservedRevision|对应观测序号|关联实际状态'),diagram=D('sequence','持续命令的回执时序（扩展设计）',['EFB','命令接口','宿主执行器','状态接口'],[(0,1,'commandId + 目标'),(1,0,'accepted'),(1,2,'提交动作'),(2,3,'更新过程状态'),(3,0,'快照 / running'),(2,1,'完成条件成立'),(1,0,'completed')])) ,
P('断线、重连与能力降级','''连接中断后，前端保留最后快照用于解释界面，但将其质量标记为过期。控制入口依据连接状态与能力清单降级，避免用户把旧观测当作当前飞机状态。航班编辑和本地纯计算可以继续，因为它们不依赖实时控制链。

重连先重新确认会话身份。若 sessionId 或机型版本变化，前端丢弃旧会话的实时观测和待关联回执；本地航班草稿可以保留，但需要重新判断机型适用性。相同会话恢复时按序号取得最新状态，跳过过期消息。

能力清单是显式的功能开关来源。后端未声明推回控制时，前端不应尝试用其他未公开接口拼接该能力。前端可以展示不可用原因，使页面结构保持完整而不产生虚假的可操作入口。''',diagram=D('state','宿主连接状态（扩展设计）',['未连接','连接建立中','已连接','连接中断','重新识别会话'],[(0,1,'发起连接'),(1,2,'身份与能力就绪'),(2,3,'通信失败'),(3,4,'恢复连接'),(4,2,'会话确认')]),table=T('连接情况|显示策略|控制策略','未连接|显示连接身份为空|宿主命令不可用\n已连接|显示最新有效快照|按能力与状态开放\n中断|保留值并标记过期|停止新增控制命令\n同会话恢复|接收新序号|重新取得请求状态\n新会话连接|重置旧观测关联|重新匹配机型与能力')) ,refs=['SIM','L-H'],scope='本节为真实模拟器后端接入的接口设计，当前本地静态服务尚未实现')
S(c,'资料服务与文件接口',
P('资料请求的领域边界','''航图、天气和机场资料来自不同服务，但页面更适合使用稳定的领域对象。资料适配器负责把提供商响应转成机场、天气或航图索引，把认证与网络错误转成统一的服务状态。页面保留资料来源与时间，而不是直接展示未经解释的传输字段。

航图内容通常同时包含索引和图像资源。机场检索返回可选图表，用户选择后再取得具体页面及主题版本。天气则包含观测文本和解码值，两者应保持同一来源时刻，避免风来自新报文而气压仍来自旧报文。

当前浏览器交付保留原生资料页面，没有配置可用的商业服务凭据。资料服务边界使这些页面可以独立接入，而不影响本地航班工作台和参考算法。''',diagram=D('components','资料服务适配边界',['资料页面','领域资料对象','提供商适配器','认证状态','网络响应','本地内容服务'],[(0,1,'读取'),(2,1,'转换'),(3,2,'授权'),(4,2,'响应'),(5,1,'文件资料')]),table=T('资料对象|关键属性|页面用途','机场|标识、名称、跑道资料|检索与选择\n天气|原文、时间、风温压|气象显示或输入来源\n航图索引|图号、类型、标题、提供商|列表与分类\n航图页面|页码、资源、边界信息|浏览与定位\n服务状态|连接、授权、错误|解释内容可用性')),
P('本地文件与资料文件的差异','''航班 JSON 和航图文件属于不同接口。前者是应用定义的结构化数据，由 parseFlight 校验；后者是供资料阅读器呈现的图片或 PDF，需要相应本地资料服务或浏览器文件接口。不能把“支持 JSON 导入”扩展解释为“任意文档都能导入签派”。

原生本地航图入口与 SimBridge 等资料访问能力相关，界面中的本地二字描述资料来源，不等于静态 EFB 服务自动暴露了用户硬盘。文件访问应通过明确选择、目录配置或服务提供，不能让页面任意读取其他目录。

报告导出是单向文件生成。它把已经有效的结果转换为 HTML 或打印页面，不承担航图索引或机场资料的维护职责。分清文件类别，可以让用户在正确入口使用正确格式。''',table=T('文件类别|入口|读取或生成规则','航班 JSON|本地工作台导入|Flight 模式与机型校验\n结果 JSON|参考结果导出|有效 Result 快照\nHTML 报告|报告导出或打印|转义文本与完整快照\n本地航图|原生本地资料页面|依赖对应资料服务\n机型配置 JSON|应用启动|由固定发布路径读取\n源码文件|构建工具|不作为用户业务文件导入'),diagram=D('tree','文件接口按内容类型区分',['文件与资料',['业务交换','航班 JSON','结果 JSON'],['可读文档','HTML 报告','打印 PDF'],['资料阅读','航图图片','航图 PDF'],['系统配置','机型与客舱','参考资料包']])) ,
P('接口来源、时效和错误说明','''一项资料进入业务流程时，需要同时保留内容、来源和时间。只保存一个数值会丢失它为何可信、何时取得以及适用于哪种环境的信息。当前手工跑道 source 是最小来源说明，外部服务接入可以扩展为结构化 provenance 对象。

错误处理区分无内容与请求失败。某机场没有某类航图属于合法空结果；授权失败、网络超时和内容解析失败则属于不同错误。页面需要给出可理解的状态，同时保留足够的诊断标识供维护者追踪。

当资料用于计算输入时，更新资料不能静默改写已经导出的报告。新资料形成新的 Flight 输入和签名，产生新结果；旧报告继续描述它生成时的快照。这使资料更新和结果追溯之间保持稳定关系。''',diagram=D('entity','资料内容与来源元数据（扩展设计）',[['内容 Content','机场 / 天气 / 图表','数值与单位'],['来源 Provenance','provider / sourceId','周期 / 取得时间'],['质量 Quality','有效 / 过期 / 缺失','错误码与说明']],[(1,0,'说明来源'),(2,0,'限定使用')]),table=T('返回情况|语义|界面表达','成功且有内容|资料可显示|内容及来源时间\n成功但空集合|没有匹配资料|无结果说明\n未授权|访问条件不满足|账户或授权提示\n超时或断线|尚未取得当前资料|重试或连接说明\n内容过期|有旧资料但时效不足|时间与过期标识\n解析失败|响应不符合领域格式|保留错误类别')) ,refs=['EFB','CHART','NAV','AUTH','L-F'])

c=C(6,'界面框架与交互设计','第一篇  系统总体设计')
S(c,'导航结构与页面路由',
P('一级业务域与二级标签','''界面导航采用两级结构。左侧工具栏选择仪表盘、签派、地面、性能、导航资料、管制、故障、检查单、预设和设置等一级业务域；页面顶部标签选择域内子页面。这种结构保持入口稳定，同时允许一个业务域继续扩展。

本地航班加入签派域，本地起飞参考加入性能域。新增页面使用原生工具栏和状态栏，避免出现第二套全局导航。地面页增加的计划条只提供上下文摘要及返回工作台的入口，不代替原生燃油、载重等标签。

导航顺序与常用工作顺序相近，但不会强迫所有功能按固定步骤使用。用户可以从检查单进入资料页面，也可以从工作台直接进入性能页；业务前置条件由状态层解释，不能仅依赖“用户应该先走过某页”。''',diagram=D('tree','主要路由结构',['EFB 内部路由',['/dispatch','local-flight','ofp / overview'],['/ground','services / fuel','payload / pushback'],['/performance','local-takeoff','top-of-descent / landing'],['其他业务域','navigation / checklists','failures / settings']]),table=T('一级入口|二级功能|主要对象','签派|本地航班、OFP、概览|计划与资料\n地面|服务、燃油、载重、推回|目标与宿主状态\n性能|离线参考、TOD、着陆|计算输入与结果\n导航|在线、本地、固定航图|资料索引及视图')),
P('MemoryRouter 的运行语义','''原生 EFB 使用 MemoryRouter，路由历史保存在应用内存中。工具栏点击改变内部 history，浏览器地址栏可以一直停留在根地址。这适合嵌入模拟器仪表的运行方式，因为业务导航不需要依赖宿主 URL。

静态服务支持无扩展路径回退到 index.html，但这一回退只保证入口文件能够打开，不意味着浏览器直接访问 /ground/fuel 就一定恢复该业务标签。应用内部的初始路由仍由 MemoryRouter 决定。使用说明因此以导航按钮而不是手工拼接 URL 为主。

本地开发钩子 __EFB_NAVIGATE 调用同一内部 history，用于采集页面和调试。它不是公开业务 API，也不是通过修改 location.pathname 维持页面状态。地面目标失效等规则直接监听业务事件，与地址栏无关。''',diagram=D('sequence','内部路由与浏览器 URL',['工具栏','MemoryRouter','业务页面','浏览器地址栏'],[(0,1,'history.push(route)'),(1,2,'匹配 Route'),(2,2,'渲染所选模块'),(1,3,'不要求同步 URL')]),table=T('行为|内部路由|地址栏','点击左侧工具栏|更新|通常保持根地址\n点击二级标签|更新|通常保持根地址\n刷新整个页面|重新建立|仍访问静态入口\n手工输入深层路径|入口可以回退|不保证标签恢复\n开发导航钩子|调用内部 history|不模拟浏览器跳转')),
P('跨页面上下文的保持','''页面之间共享航班身份与确认状态，而各自保留局部视图状态。工作台负责编辑，仪表盘负责摘要，参考页负责当前计算，地面页负责目标和观测。切换页面不会因为组件离开屏幕就把航班变成另一个对象。

一些视图状态具有页面局部性质，例如图表缩放、选中标签、表单显示单位和当前搜索词。它们不必全部进入 Flight。把显示单位误存成业务单位，会使“只切换显示”也改变签名和计算输入，因此两者在组件中分开管理。

返回入口应明确告诉用户回到哪个业务对象。参考页的“编辑航班与重量”返回当前工作台，地面计划条显示当前航班号和重量摘要。用户由此可以判断自己正在操作哪一份计划。''',table=T('状态|存放范围|跨页意义','Flight 与确认|本地共享状态|同一航班上下文\n参考 Result|本地共享状态|结果与输入关系\n原生配置|共享 Store|所有相关页面使用\n显示质量单位|工作台组件状态|只改变输入展示\n航图缩放与旋转|导航页面状态|恢复阅读位置\n搜索词或标签|对应业务切片|保存界面选择'),diagram=D('components','共享业务状态与局部视图状态',['共享 Flight','工作台视图','仪表盘视图','性能视图','地面视图','各页局部状态'],[(0,1,'输入'),(0,2,'投影'),(0,3,'计算上下文'),(0,4,'计划摘要'),(5,1,'显示单位')])) ,refs=['EFB','L-U','L-S'])
S(c,'表单、单位与输入反馈',
P('字段组件与可访问标签','''本地字段组件把文字标签和输入控件组合成一个单元，并提供 aria-label 和稳定的 data-field。可读标签服务用户和辅助技术，稳定字段名服务组件识别与维护，二者可以采用不同语言但对应同一业务字段。

数值输入的空值转换为 NaN，而不是默默当作 0。这样用户清空一个字段时，校验能够报告缺失的有效数值，而不会把意外空白解释成合法零重量或零距离。格式化函数对非有限数显示占位符，避免 NaN 直接成为业务结果。

部分字段只读，例如当前资料包固定 OEW。只读显示允许用户看见计算所用基准，又避免通过任意修改绕过资料包身份。字段能否编辑由业务语义决定，不仅由视觉样式决定。''',diagram=D('components','字段组件的数据往返',['标签与 aria-label','输入控件','文本解析','领域数值','格式化显示'],[(0,1,'解释含义'),(1,2,'用户输入'),(2,3,'number / NaN'),(3,4,'格式化'),(4,1,'当前显示')]),table=T('输入情况|内部表示|反馈','有效数字|number|正常派生与显示\n清空数值框|NaN|输入待修正\n机场小写输入|转为大写文本|按 ICAO 规则校验\n只读 OEW|固定资料值|可见但不可任意编辑\n无效结果数值|null 或非有限值|显示占位符')),
P('显示单位与内部单位','''内部模型保持固定单位，用户选择只改变字段的显示和输入转换。工作台从 kg 换成 lb 时，用 massConvert 把内部值转换后显示；用户修改该字段时，再从 lb 转回 kg 保存。单纯改变下拉框不会重写原始业务值。

距离和压力采用同样机制。跑道距离可在 m 与 ft 间显示，QNH 可在 hPa 与 inHg 间显示。标高字段明确使用 ft，不随跑道距离单位一起变化。标签直接写出当前单位，使局部设置的作用范围可见。

显示精度和计算精度分开。输入控件为可读性限制小数位，领域计算保留内部数值；结果卡片和报告根据场景格式化。单位往返时不能不断把显示舍入结果当作唯一原始值，否则反复切换会累积误差。''',diagram=D('sequence','显示单位切换与输入换算',['内部模型','显示转换','输入控件','编辑动作'],[(0,1,'固定 kg / m / hPa'),(1,2,'转换到当前显示单位'),(2,3,'用户输入新数值'),(3,3,'换回内部单位'),(3,0,'更新 Flight')]),table=T('物理量|内部单位|可选显示单位','质量|kg|kg / lb\n跑道长度|m|m / ft\n压力|hPa|hPa / inHg\n跑道标高|ft|ft\n风速与参考速度|kt|kt\n方向|degree|degree')),
P('即时反馈与提交反馈','''即时反馈针对草稿内容，例如质量卡片和输入错误列表。提交反馈针对一个动作是否完成，例如“本地航班与重量已确认”。两者同时存在，使用户既能边输入边理解合计，也能知道当前计划是否已进入共享业务流程。

计算按钮不通过页面颜色判断能否计算，而由 runCalculation 检查确认内容和地面变化。结果出口按钮使用 currentResult 的布尔值禁用或启用。页面的视觉状态和应用层规则因此使用同一个有效性来源。

错误提示尽量说明原因和下一步入口。文件导入失败说明原航班被保留；结果过期说明需要重新确认并计算；模型不支持说明是哪一种条件超出范围。这样的文字直接服务用户，不要求用户理解内部异常栈。''',table=T('反馈类型|出现位置|表达内容','草稿合计|重量卡片|当前输入派生值\n字段错误|输入待修正区域|具体字段或范围\n动作成功|状态消息条|已确认、已保存等\n结果过期|结果标题与出口按钮|当前值不再可用\n模型不支持|结果原因列表|对应条件尚无修正\n存储失败|优先状态消息|建议导出以保存工作'),diagram=D('state','结果卡片的可见状态',['等待计算','输入无效','超出支持范围','参考表核算完成','结果已过期'],[(0,1,'校验失败'),(0,2,'范围拒绝'),(0,3,'支持范围内'),(3,4,'输入或目标变化')])) ,refs=['L-U','L-F','L-S'])
S(c,'布局、缩放与长内容',
P('逻辑画布与可视区域','''原生 EFB 以平板尺寸组织布局，浏览器宿主采用 1430×1000 逻辑画布承载它。缩放比例取浏览器可用宽度比例与可用高度比例中的较小值，使整幅画布保持比例。底部模式说明条单独占据浏览器空间。

画布内部的 viewport 类转换为逻辑尺寸，避免 w-screen 先使用浏览器窄宽度，再整体缩放一次导致内容二次缩小。仪表容器的物理宽高则设为缩放后的值，不保留一个不可见但仍撑开滚动条的原始大盒子。

窄侧栏中可以完整看到页面，但阅读和输入仍更适合较宽窗口。设计目标是保持完整布局与可达性，而不是把原生平板每个复杂页面重新排成手机纵向表单。''',diagram=D('formula','浏览器缩放关系',[['宽度比例','Sw = viewportWidth / 1430'],['高度比例','Sh = (viewportHeight - bannerHeight) / 1000'],['最终比例','S = min(Sw, Sh)；显示尺寸 = 1430S × 1000S']]),table=T('布局对象|尺寸依据|目的','逻辑画布|1430×1000|保持原生布局\n显示容器|逻辑尺寸乘缩放率|不产生隐形溢出\n模式说明条|实际内容高度|为页脚预留空间\n内部 w-screen / h-screen|逻辑画布尺寸|避免双重缩放\n窗口变化|resize 与尺寸观察|动态重新计算')),
P('长页面和局部滚动','''本地工作台、历史记录及原生载重页面包含较多内容，采用页面内容区滚动，而不是让浏览器整页无限拉长。工具栏和状态上下文因此保持稳定，用户可以在业务域内查找较低位置的控件。

地面页顶部新增计划摘要后，原生内容区的可用高度相应减少。宿主样式为地面内容提供明确高度及纵向滚动，使燃油目标和下方载重控制仍可到达。只在外层裁切画布而不处理内部高度，会隐藏底部按钮。

滚动是内容布局的一部分。操作说明在控件位于首屏以下时明确提示在地面内容区下滚，而不把隐藏在下方的按钮描述为缺失功能。''',diagram=D('layers','固定导航与局部滚动的空间分配',['固定状态栏：时间、连接、快速控制','业务标题与标签','计划上下文条（地面模块）','可滚动业务内容：表单、油箱、座位及控制','独立模式说明条：宿主运行身份']),table=T('区域|滚动行为|典型内容','全局工具栏|固定在平板布局中|一级导航\n地面内容区|纵向滚动|载重下部控制\n工作台|内容区可浏览|完整字段与提示\n历史区域|随业务内容延展|近期记录列表\nOFP 阅读区|文档自身滚动|长签派资料\n报告窗口|浏览器文档滚动|输入快照与打印内容')),
P('界面、报告与无数据状态','''交互界面使用原生深色主题，适合显示高密度仪表信息；报告使用白底、明确标题和普通文档行距，适合阅读与打印。两种表现形式读取同一数据快照，因此改变输出媒介不会改变计算来源。

无数据状态是正常业务状态的一部分。尚未确认航班时，首页显示编辑入口；没有历史时，历史区解释如何保存；没有固定航图时，页面保留导航入口。空态需要提供对象含义及可用动作，不能只剩无标识的空白背景。

本地版启动修订也遵循这一原则：加载时显示启动状态，休眠时显示唤醒按钮。页面无法提供外部资料时，用户仍应能辨认软件在运行，并知道哪些区域取决于外部连接。''',table=T('界面状态|表达方式|可用动作','未确认航班|文字与编辑按钮|进入工作台\n未计算|等待计算提示|确认后计算\n无历史记录|空列表说明|保存有效结果\n无固定航图|资料空态|进入航图页面\n平板休眠|休眠文字与按钮|唤醒\n报告阅读|白底文档与范围说明|保存、打印'),diagram=D('components','相同数据的不同呈现',['Flight / Result','深色交互页面','白底 HTML 报告','JSON 数据文件'],[(0,1,'交互视图'),(0,2,'阅读视图'),(0,3,'交换视图')])) ,refs=['L-H','L-U','EFB'])
S(c,'状态提示与操作一致性',
P('状态提示的分级','''提示按对当前动作的影响分级。普通通知说明已保存或已恢复；输入错误阻止确认；模型范围说明阻止生成参考速度；结果过期阻止归档与报告；存储错误说明当前工作尚未可靠保存。不同级别对应不同操作后果。

颜色只是提示的一部分。结果卡片同时显示状态标题、具体原因及按钮可用性，用户可以从文字理解问题。报告保留能力范围说明，使离开交互界面的文件仍能表达结果性质。

全局模式条持续标识浏览器开发模式和本地模拟数据。这是运行身份信息，不随用户进入某个页面而消失。与局部状态提示相比，它回答的是“当前软件连接了什么”，而不是“刚才这一步是否完成”。''',diagram=D('layers','从运行身份到局部动作的提示层次',['运行身份：浏览器开发模式 / 宿主连接身份','航班状态：草稿、已确认、地面变化','计算状态：等待、无效、不支持、参考完成、过期','动作反馈：导入、保存、导出、打印','字段反馈：格式、数值、单位与范围']),table=T('提示层次|有效范围|示例','运行模式|整个应用会话|本地模拟数据\n业务状态|当前航班|等待确认重量\n计算状态|当前 Result|结果已过期\n动作通知|最近用户动作|导入失败保留原航班\n字段错误|具体输入|滑行耗油超过停机坪油')),
P('破坏有效性的动作保持可见','''输入改变会清除确认并使旧结果失效。界面保留原数字时必须同时呈现过期状态，避免用户仅因数字仍在屏幕上就继续使用。导出按钮的禁用和过期提示共同表达这一变化。

恢复历史与读取地面燃油目标也属于输入改变，而不是“撤销过期”的快捷方式。两者形成新的当前草稿，随后经过确认与计算。这样用户无论从哪个入口改变数据，都遵循相同的有效性规则。

当前实现中的按钮顺序把编辑、确认、计算、保存和导出分开呈现。动作数量并不是目的；每个动作对应不同的数据状态，因而可以在说明书中清楚解释其结果。''',diagram=D('sequence','输入修改后的可见反馈',['用户','输入状态','结果选择器','界面出口'],[(0,1,'修改字段或恢复历史'),(1,1,'清空确认'),(1,2,'签名不再匹配'),(2,3,'返回 null'),(3,0,'显示过期并禁用导出')]),table=T('用户动作|数据变化|界面后果','修改输入|新 Flight|等待确认\n读取燃油目标|rampKg 改变|旧结果过期\n恢复历史|input 载入为草稿|需要重算\n地面目标修改|groundChanged=true|导出不可用\n确认并计算|新 Result|符合条件时恢复出口')),
P('一致的异常恢复路径','''恢复路径尽量回到用户熟悉的业务入口。输入错误留在当前表单修正；文件错误允许选择另一个文件；过期结果引导重新确认；打印弹窗被阻止时提供 HTML 导出；外部资料失败保持本地业务可用。恢复不要求用户使用开发控制台修改内部变量。

刷新页面是重新装载应用，而不是通用的业务提交动作。未成功持久化的内容可能无法通过刷新恢复，已保存的草稿则可以重新读取。因此保存错误提示优先于普通通知，提醒用户先通过文件保留工作。

操作说明中的异常处理只描述用户可以执行的动作。内部日志、源码路径和接口语义放在设计与维护部分，避免把最终使用者的操作流程写成开发调试任务清单。''',table=T('问题|用户恢复入口|保留的数据','字段不合法|当前表单|草稿\n文件格式不正确|重新选择 JSON|原航班\n结果过期|保存确认与本地计算|当前输入\n浏览器阻止打印窗口|导出报告 HTML|有效结果\n本机存储失败|导出航班 JSON|当前内存草稿\n外部资料不可用|账户或连接设置|本地计划与计算\n平板休眠|唤醒 EFB|业务会话'),diagram=D('tree','按问题选择恢复入口',['可恢复问题',['输入','字段修正','重新确认'],['文件','重新选择','保留原数据'],['输出','HTML 下载','浏览器打印'],['运行','唤醒 / 刷新','连接设置']])) ,refs=['L-U','L-S','L-H'])
